function [d] = elastic2(r_moon, r_sun, k2, mu, re)
%ELASTIC2  solidtides.elastic2(rMoon_ecef, rSun_ecef, k2, mu, Re): the degree-2 elastic tide of one real Love number.
%   r_moon: real[1][3] (passed a plain number)
%   r_sun: real[1][3] (passed a plain number)
%   k2: real[1] (passed a plain number)
%   mu: real[1] (passed a plain number)
%   re: real[1] (passed a plain number)
%   returns d: Dcs5 (passed rec)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    d = asils.models.solidtides.Dcs5_zero();
    k4 = asils.models.de440.de440_constants();
    d = asils.models.solidtides.Dcs5_zero();
    for b = (0):((2) - 1)
        rb = asils.pc.choose((b == 0), r_moon, r_sun);
        gmb = asils.pc.choose((b == 0), k4.gm_moon, k4.gm_sun);
        [r, phi, lam] = asils.models.solidtides.body_angles(rb);
        p = asils.models.solidtides.norm_legendre5(sin(phi), 2);
        for m = (0):((3) - 1)
            fac = ((((k2 / 5) * (gmb / mu)) * asils.pc.pow_((re / r), 3)) * p(3, (m) + 1));
            d.dc(3, (m) + 1) = (d.dc(3, (m) + 1) + (fac * cos((m * lam))));
            d.ds(3, (m) + 1) = (d.ds(3, (m) + 1) + (fac * sin((m * lam))));
        end
    end
end
